/** Lower-case and strip accents, so "dërë", "dere" and "DERE" all match. */
export const norm = (s: string) => s.toLowerCase().normalize("NFD").replace(/\p{M}/gu, "").replace(/[^\p{L}\p{N}²³.,€ ]+/gu, " ").replace(/\s+/g, " ").trim();

