function lev(a: string, b: string) {
  if (Math.abs(a.length - b.length) > 2) return 9;
  const d = Array.from({ length: a.length + 1 }, (_, i) => [i, ...Array(b.length).fill(0)]);
  for (let j = 1; j <= b.length; j++) d[0][j] = j;
  for (let i = 1; i <= a.length; i++) for (let j = 1; j <= b.length; j++) {
    d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    // Swapped neighbours ("tilse" → "tiles") count as one typo.
    if (i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) d[i][j] = Math.min(d[i][j], d[i - 2][j - 2] + 1);
  }
  return d[a.length][b.length];
}
/** Close enough to a vocabulary word: exact, plural/singular, or one typo (two for long words). */
export function near(token: string, word: string) {
  if (token === word || token === `${word}s` || `${token}s` === word || token === `${word}es`) return true;
  // Typos only for longer words and only when the first letter matches ("tabl" is not "cable").
  if (token.length < 4 || word.length < 5 || token[0] !== word[0]) return false;
  return lev(token, word) <= (word.length >= 7 ? 2 : 1);
}

/** Categories mentioned in the text (most specific first). */
/** Real words that sit one or two letters from a material word ("furnitor" = supplier, not "furniture"). */
const NOT_MATERIALS = new Set(["furnitor", "furnitore", "furnitori", "furnitoret", "furnitorin", "furnizim", "furnizues"]);

export function categoriesIn(text: string): string[] {
  const n = norm(text);
  const found = new Set<string>();
  for (const [p, c] of PHRASES) if (n.includes(p)) found.add(c);
  const tokens = n.split(" ").filter((tk) => !NOT_MATERIALS.has(tk));
  for (const [cat, words] of Object.entries(LEXICON)) if (tokens.some((tk) => words.some((w) => near(tk, w)))) found.add(cat);
  return [...found];
}
export const mentionsFloor = (text: string) => norm(text).split(" ").some((tk) => FLOOR_WORDS.some((w) => near(tk, w)));

export const categoryLabel = (id: string, lang: Lang) => MARKET_CATEGORIES.find((c) => c.id === id)?.[lang] ?? id;

/** Answer in the language the person wrote in when it is clear; otherwise keep the site language. */
export function detectLang(text: string, fallback: Lang): Lang {
  const raw = text.toLowerCase();
  if (/[ëç]/.test(raw)) return "sq";
  const n = norm(text).split(" ");
  const SQ = ["gjej", "dua", "kam", "me", "per", "dhe", "ne", "nje", "te", "shes", "kerko", "duhen", "duhet", "ku", "sa", "cfare", "si", "pllaka", "tulla", "dysheme", "parket", "dyer", "shporta", "rinovoj", "hap", "shiko", "afer", "lire", "porosite"];
  const EN = ["find", "want", "need", "the", "of", "in", "near", "my", "show", "add", "what", "how", "sell", "cheapest", "about", "tiles", "bricks", "doors", "floor", "flooring", "wood", "open"];
  const sq = n.filter((w) => SQ.includes(w)).length, en = n.filter((w) => EN.includes(w)).length;
  return sq > en ? "sq" : en > sq ? "en" : fallback;
}
